class Main {
    static class Box {
        // 공유할 횟수 칸의 선언을 고쳐요.
        int visits;
        Box() {
            // 생성할 때마다 횟수를 하나 늘려요.
            visits++;
        }
    }

    public static void main(String[] args) {
        // 이번 실험의 시작값이에요.
        int n = 3;
        Box.visits = n;
        // 객체를 두 번 만들고 누적 횟수를 읽어요.
        new Box();
        new Box();
        System.out.println(Box.visits);
    }
}
